<span class="line"><span style="color:#E1E4E8;">        </span><span style="color:#79B8FF;">&quot;presigned_url&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;https://storage.googleapis.com/...&quot;</span><span style="color:#E1E4E8;">,</span></span>
